// group-sales | group-by-region / hash-map | negative / p3

use std::collections::HashMap;

#[derive(Debug, Clone)]
struct Sale {
    id: u32,
    region: &'static str,
    amount: i64,
}

fn group_by_region(sales: &[Sale]) -> Vec<(String, i64)> {
    let mut totals: HashMap<&str, i64> = HashMap::new();
    for sale in sales {
        *totals.entry(sale.region).or_insert(0) += sale.amount;
    }

    let mut entries: Vec<(String, i64)> = totals
        .into_iter()
        .map(|(region, total)| (region.to_string(), total))
        .collect();
    entries.sort_by(|left, right| right.1.cmp(&left.1).then_with(|| left.0.cmp(&right.0)));
    entries
}

fn main() {
    let sales = vec![
        Sale { id: 1, region: "north", amount: -7 },
        Sale { id: 2, region: "south", amount: -13 },
        Sale { id: 3, region: "east", amount: 0 },
        Sale { id: 4, region: "west", amount: 7 },
        Sale { id: 5, region: "north", amount: 4 },
    ];
    for (region, total) in group_by_region(&sales) {
        println!("{region}={total}");
    }
}

// safe-division | divide / result-question-mark | large / p4
// Compact variant.

#[derive(Debug, PartialEq)]
enum MathError {
    DivideByZero,
    OutOfRange,
}

fn divide_v2(numerator: i64, denominator: i64) -> Result<i64, MathError> {
    if denominator == 0 {
        return Err(MathError::DivideByZero);
    }
    let result = numerator.checked_div(denominator).ok_or(MathError::OutOfRange)?;
    if result.abs() > 2000 {
        return Err(MathError::OutOfRange);
    }
    Ok(result)
}

fn main() {
    println!("{:?}", divide_v2(1034, 34));
    println!("{:?}", divide_v2(1034, 0));
    println!("{:?}", divide_v2(-1034, 4));
}

