// shape-trait | compute-area / dynamic-dispatch | duplicates / p3
// Documented reference implementation.

trait Shape {
    fn area(&self) -> f64;
    fn label(&self) -> &'static str;
}

struct Circle {
    radius: f64,
}

struct Rectangle {
    width: f64,
    height: f64,
}

impl Shape for Circle {
    fn area(&self) -> f64 {
        std::f64::consts::PI * self.radius * self.radius
    }

    fn label(&self) -> &'static str {
        "circle"
    }
}

impl Shape for Rectangle {
    fn area(&self) -> f64 {
        self.width * self.height
    }

    fn label(&self) -> &'static str {
        "rectangle"
    }
}

fn total_area_doc(shapes: &[Box<dyn Shape>]) -> f64 {
    shapes.iter().map(|shape| shape.area()).sum()
}

fn main() {
    let shapes: Vec<Box<dyn Shape>> = vec![
        Box::new(Circle { radius: 2.0 }),
        Box::new(Rectangle { width: 11.0, height: 11.0 }),
    ];
    for shape in &shapes {
        println!("{}={:.2}", shape.label(), shape.area());
    }
    println!("total={:.2}", total_area_doc(&shapes));
}

