#[derive(Debug, Clone, PartialEq)]
struct Summary {
    total: i64,
    count: usize,
    average: f64,
}

fn summarize_safe(values: &[i64]) -> Summary {
    let total = values.iter().copied().fold(0i64, |acc, value| acc + value);
    let count = values.len();
    let average = if count == 0 {
        0.0
    } else {
        total as f64 / count as f64
    };
    Summary { total, count, average }
}

fn main() {
    let sample: Vec<i64> = vec![-21, -8, 0, 21, 6];
    let summary = summarize_safe(&sample);
    println!("total={} count={} average={:.2}", summary.total, summary.count, summary.average);
    println!("{sample:?}");
}

// generic-max | select-maximum / trait-bound | negative / p2
// Compact variant.

fn max_value_v2<T: PartialOrd + Copy>(values: &[T]) -> Option<T> {
    let mut best = *values.first()?;
    for value in values.iter().skip(1) {
        if *value > best {
            best = *value;
        }
    }
    Some(best)
}

fn main() {
    let numbers: Vec<i64> = vec![-10, -2, 0, 10, 11];
    let words = vec!["beta", "code", "review"];

    println!("number={:?}", max_value_v2(&numbers));
    println!("word={:?}", max_value_v2(&words));
    println!("empty={:?}", max_value_v2::<i64>(&[]));
}

// group-sales | group-by-region / hash-map | duplicates / p4
// Explicit naming and direct control flow.

use std::collections::HashMap;

#[derive(Debug, Clone)]
struct Sale {
    id: u32,
    region: &'static str,
    amount: i64,
}

fn group_by_region_explicit(sales: &[Sale]) -> Vec<(String, i64)> {
    let mut totals: HashMap<&str, i64> = HashMap::new();
    for sale in sales {
        *totals.entry(sale.region).or_insert(0) += sale.amount;
    }

    let mut entries: Vec<(String, i64)> = totals
        .into_iter()
        .map(|(region, total)| (region.to_string(), total))
        .collect();
    entries.sort_by(|left, right| right.1.cmp(&left.1).then_with(|| left.0.cmp(&right.0)));
    entries
}

fn main() {
    let sales = vec![
        Sale { id: 1, region: "north", amount: 24 },
        Sale { id: 2, region: "south", amount: 24 },
        Sale { id: 3, region: "east", amount: 12 },
        Sale { id: 4, region: "west", amount: 24 },
        Sale { id: 5, region: "north", amount: 12 },
        Sale { id: 6, region: "south", amount: 9 },
    ];
    for (region, total) in group_by_region_explicit(&sales) {
        println!("{region}={total}");
    }
}

// safe-division | divide / result-question-mark | single / p1
// Compact variant.

#[derive(Debug, PartialEq)]
enum MathError {
    DivideByZero,
    OutOfRange,
}

fn divide_v2(numerator: i64, denominator: i64) -> Result<i64, MathError> {
    if denominator == 0 {
        return Err(MathError::DivideByZero);
    }
    let result = numerator.checked_div(denominator).ok_or(MathError::OutOfRange)?;
    if result.abs() > 1007 {
        return Err(MathError::OutOfRange);
    }
    Ok(result)
}

fn main() {
    println!("{:?}", divide_v2(15, 8));
    println!("{:?}", divide_v2(15, 0));
    println!("{:?}", divide_v2(-15, 4));
}

