#[derive(Debug)]
struct History {
    entries: Vec<String>,
    limit: usize,
}

impl History {
    fn new(limit: usize) -> Self {
        History {
            entries: Vec::new(),
            limit,
        }
    }

    fn apply_explicit(&mut self, action: &str) {
        if self.entries.len() == self.limit {
            self.entries.remove(0);
        }
        self.entries.push(action.to_string());
    }

    fn undo(&mut self) -> Option<String> {
        self.entries.pop()
    }
}

