use std::collections::HashMap;

#[derive(Debug, Clone)]
struct Sale {
    id: u32,
    region: &'static str,
    amount: i64,
}

fn group_by_region_v2(sales: &[Sale]) -> Vec<(String, i64)> {
    let mut totals: HashMap<&str, i64> = HashMap::new();
    for sale in sales {
        *totals.entry(sale.region).or_insert(0) += sale.amount;
    }

    let mut entries: Vec<(String, i64)> = totals
        .into_iter()
        .map(|(region, total)| (region.to_string(), total))
        .collect();
    entries.sort_by(|left, right| right.1.cmp(&left.1).then_with(|| left.0.cmp(&right.0)));
    entries
}

fn main() {
    let sales = vec![
        Sale { id: 1, region: "north", amount: -3 },
        Sale { id: 2, region: "south", amount: -5 },
        Sale { id: 3, region: "east", amount: 0 },
        Sale { id: 4, region: "west", amount: 3 },
        Sale { id: 5, region: "north", amount: 7 },
    ];
    for (region, total) in group_by_region_v2(&sales) {
        println!("{region}={total}");
    }
}

