// undo-stack | undo-history / vec-as-stack | large / p4
// Defensive variant with descriptive identifiers.

#[derive(Debug)]
struct History {
    entries: Vec<String>,
    limit: usize,
}

impl History {
    fn new(limit: usize) -> Self {
        History {
            entries: Vec::new(),
            limit,
        }
    }

    fn apply_safe(&mut self, action: &str) {
        if self.entries.len() == self.limit {
            self.entries.remove(0);
        }
        self.entries.push(action.to_string());
    }

    fn undo(&mut self) -> Option<String> {
        self.entries.pop()
    }
}

fn main() {
    let mut history = History::new(6);
    for index in 0..14 {
        history.apply_safe(&format!("action-{index}"));
    }
    println!("undo={:?}", history.undo());
    println!("remaining={}", history.entries.len());
}

