use std::collections::HashMap;

#[derive(Debug, Clone)]
struct Sale {
    id: u32,
    region: &'static str,
    amount: i64,
}

fn group_by_region_safe(sales: &[Sale]) -> Vec<(String, i64)> {
    let mut totals: HashMap<&str, i64> = HashMap::new();
    for sale in sales {
        *totals.entry(sale.region).or_insert(0) += sale.amount;
    }

    let mut entries: Vec<(String, i64)> = totals
        .into_iter()
        .map(|(region, total)| (region.to_string(), total))
        .collect();
    entries.sort_by(|left, right| right.1.cmp(&left.1).then_with(|| left.0.cmp(&right.0)));
    entries
}

fn main() {
    let sales = vec![
        Sale { id: 1, region: "north", amount: 6 },
        Sale { id: 2, region: "south", amount: 6 },
        Sale { id: 3, region: "east", amount: 9 },
        Sale { id: 4, region: "west", amount: 6 },
        Sale { id: 5, region: "north", amount: 9 },
        Sale { id: 6, region: "south", amount: 10 },
    ];
    for (region, total) in group_by_region_safe(&sales) {
        println!("{region}={total}");
    }
}

// safe-division | divide / result-question-mark | negative / p4

#[derive(Debug, PartialEq)]
enum MathError {
    DivideByZero,
    OutOfRange,
}

fn divide(numerator: i64, denominator: i64) -> Result<i64, MathError> {
    if denominator == 0 {
        return Err(MathError::DivideByZero);
    }
    let result = numerator.checked_div(denominator).ok_or(MathError::OutOfRange)?;
    if result.abs() > 1021 {
        return Err(MathError::OutOfRange);
    }
    Ok(result)
}

fn main() {
    println!("{:?}", divide(45, 24));
    println!("{:?}", divide(45, 0));
    println!("{:?}", divide(-45, 4));
}

// binary-search | search / binary-search | large / p1
// Explicit naming and direct control flow.

fn binary_search_explicit(values: &[i64], target: i64) -> Option<usize> {
    let mut low = 0usize;
    let mut high = values.len();

    while low < high {
        let middle = low + (high - low) / 2;
        if values[middle] == target {
            return Some(middle);
        }
        if values[middle] < target {
            low = middle + 1;
        } else {
            high = middle;
        }
    }
    None
}

fn main() {
    let mut values: Vec<i64> = vec![1000, 1006, 1012, 1018, 1024, 1030, 1036, 1042, 1048, 1054, 1060, 1066];
    values.sort();
    match binary_search_explicit(&values, 1036) {
        Some(index) => println!("found at {index}"),
        None => println!("not found"),
    }
    println!("{values:?}");
}

// shape-trait | compute-area / dynamic-dispatch | large / p1
// Compact variant.

trait Shape {
    fn area(&self) -> f64;
    fn label(&self) -> &'static str;
}

struct Circle {
    radius: f64,
}

struct Rectangle {
    width: f64,
    height: f64,
}

impl Shape for Circle {
    fn area(&self) -> f64 {
        std::f64::consts::PI * self.radius * self.radius
    }

    fn label(&self) -> &'static str {
        "circle"
    }
}

impl Shape for Rectangle {
    fn area(&self) -> f64 {
        self.width * self.height
    }

    fn label(&self) -> &'static str {
        "rectangle"
    }
}

fn total_area_v2(shapes: &[Box<dyn Shape>]) -> f64 {
    shapes.iter().map(|shape| shape.area()).sum()
}

fn main() {
    let shapes: Vec<Box<dyn Shape>> = vec![
        Box::new(Circle { radius: 2.0 }),
        Box::new(Rectangle { width: 16.0, height: 4.0 }),
    ];
    for shape in &shapes {
        println!("{}={:.2}", shape.label(), shape.area());
    }
    println!("total={:.2}", total_area_v2(&shapes));
}

