// binary-search | search / binary-search | negative / p1
// Documented reference implementation.

fn binary_search_doc(values: &[i64], target: i64) -> Option<usize> {
    let mut low = 0usize;
    let mut high = values.len();

    while low < high {
        let middle = low + (high - low) / 2;
        if values[middle] == target {
            return Some(middle);
        }
        if values[middle] < target {
            low = middle + 1;
        } else {
            high = middle;
        }
    }
    None
}

fn main() {
    let mut values: Vec<i64> = vec![-5, -3, 0, 3, 7];
    values.sort();
    match binary_search_doc(&values, 0) {
