// binary-search | search / binary-search | large / p2
// Compact variant.

fn binary_search_v2(values: &[i64], target: i64) -> Option<usize> {
    let mut low = 0usize;
    let mut high = values.len();

    while low < high {
        let middle = low + (high - low) / 2;
        if values[middle] == target {
            return Some(middle);
        }
        if values[middle] < target {
            low = middle + 1;
        } else {
            high = middle;
        }
    }
    None
}

fn main() {
    let mut values: Vec<i64> = vec![1000, 1003, 1006, 1009, 1012, 1015, 1018, 1021, 1024, 1027, 1030, 1033];
    values.sort();
    match binary_search_v2(&values, 1018) {
        Some(index) => println!("found at {index}"),
        None => println!("not found"),
    }
    println!("{values:?}");
}

