    println!("{score:?} maximum={}", score.is_maximum());
}

// group-sales | group-by-region / hash-map | single / p1

use std::collections::HashMap;

#[derive(Debug, Clone)]
struct Sale {
    id: u32,
    region: &'static str,
    amount: i64,
}

fn group_by_region(sales: &[Sale]) -> Vec<(String, i64)> {
    let mut totals: HashMap<&str, i64> = HashMap::new();
    for sale in sales {
        *totals.entry(sale.region).or_insert(0) += sale.amount;
    }

    let mut entries: Vec<(String, i64)> = totals
        .into_iter()
        .map(|(region, total)| (region.to_string(), total))
        .collect();
    entries.sort_by(|left, right| right.1.cmp(&left.1).then_with(|| left.0.cmp(&right.0)));
    entries
}

fn main() {
    let sales = vec![
        Sale { id: 1, region: "north", amount: 7 },
    ];
    for (region, total) in group_by_region(&sales) {
        println!("{region}={total}");
    }
}

// summary | aggregate / iterator-fold | negative / p1
// Documented reference implementation.

#[derive(Debug, Clone, PartialEq)]
struct Summary {
    total: i64,
    count: usize,
    average: f64,
}

fn summarize_doc(values: &[i64]) -> Summary {
    let total = values.iter().copied().fold(0i64, |acc, value| acc + value);
    let count = values.len();
    let average = if count == 0 {
        0.0
    } else {
        total as f64 / count as f64
    };
    Summary { total, count, average }
}

fn main() {
    let sample: Vec<i64> = vec![-3, -5, 0, 3, 7];
    let summary = summarize_doc(&sample);
    println!("total={} count={} average={:.2}", summary.total, summary.count, summary.average);
    println!("{sample:?}");
}
